define(['core/ajax','core/notification'], function(Ajax, Notification){
 const sleep=(ms)=>new Promise(r=>setTimeout(r,ms));
 const init=async(cfg)=>{const script=document.createElement('script');script.src=cfg.server.replace(/\/$/,'')+'/web-apps/apps/api/documents/api.js';script.onload=()=>{if(window.DocsAPI)new DocsAPI.DocEditor('wsg-office-editor',cfg.config);};script.onerror=()=>Notification.alert('ONLYOFFICE','Không tải được API của ONLYOFFICE Docs.');document.head.appendChild(script);const state=document.querySelector('[data-region="office-save-state"]');const request=async(intent)=>{const btn=document.querySelector(intent==='submit'?'[data-action="office-submit"]':'[data-action="office-save"]');if(btn)btn.disabled=true;if(state)state.textContent='Đang yêu cầu lưu bản mới nhất…';try{const r=await Ajax.call([{methodname:'mod_worksheetgrader_request_office_save',args:{attemptid:cfg.attemptid,intent}}])[0];for(let i=0;i<45;i++){await sleep(1000);const s=await Ajax.call([{methodname:'mod_worksheetgrader_office_save_status',args:{requestid:r.requestid}}])[0];if(['saved','submitted'].includes(s.status)){if(state)state.textContent=s.status==='submitted'?'Đã nộp':'Đã lưu';if(s.status==='submitted')window.location.assign(cfg.redirect);return;}if(s.status==='failed')throw new Error('ONLYOFFICE save failed: '+(s.errorcode||''));}throw new Error('Quá thời gian chờ ONLYOFFICE callback');}catch(e){if(state)state.textContent='Lưu thất bại';Notification.exception(e);if(btn)btn.disabled=false;}};document.querySelector('[data-action="office-save"]')?.addEventListener('click',()=>request('progress'));document.querySelector('[data-action="office-submit"]')?.addEventListener('click',()=>{if(confirm('Nộp bài? Hệ thống sẽ lưu bản mới nhất rồi khóa bài.'))request('submit');});};return {init};
});
